#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define DRONES 4

typedef struct {
    int id, battery;
} Report;

typedef struct {
    int low, mid, high;
    int weakest_id, weakest_battery;   // weakest_battery starts above 100
} Census;

Census census = { 0, 0, 0, 0, 101 };
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    const Report *reports;
    int from, to;
} Slice;

void *count_slice(void *arg) {
    Slice *s = arg;
    Census local = { 0, 0, 0, 0, 101 };
    for (int i = s->from; i < s->to; i++) {
        const Report *r = &s->reports[i];
        if (r->battery < 20) local.low++;
        else if (r->battery < 80) local.mid++;
        else local.high++;
        if (r->battery < local.weakest_battery || (r->battery == local.weakest_battery && r->id < local.weakest_id)) {
            local.weakest_battery = r->battery;
            local.weakest_id = r->id;
        }
    }
    pthread_mutex_lock(&lock);
    census.low += local.low;
    census.mid += local.mid;
    census.high += local.high;
    if (local.weakest_battery < census.weakest_battery ||
        (local.weakest_battery == census.weakest_battery && local.weakest_id < census.weakest_id)) {
        census.weakest_battery = local.weakest_battery;
        census.weakest_id = local.weakest_id;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main(void) {
    int n;
    scanf("%d", &n);
    Report *reports = malloc(n * sizeof(Report));
    if (reports == NULL) return 1;
    for (int i = 0; i < n; i++) scanf("%d %d", &reports[i].id, &reports[i].battery);

    pthread_t threads[DRONES];
    Slice slices[DRONES];
    int base = n / DRONES, extra = n % DRONES, next = 0;
    for (int i = 0; i < DRONES; i++) {
        int size = base + (i < extra ? 1 : 0);
        slices[i] = (Slice){ reports, next, next + size };
        next += size;
        pthread_create(&threads[i], NULL, count_slice, &slices[i]);
    }
    for (int i = 0; i < DRONES; i++) pthread_join(threads[i], NULL);

    printf("low %d mid %d high %d\n", census.low, census.mid, census.high);
    printf("weakest %d (%d%%)\n", census.weakest_id, census.weakest_battery);
    free(reports);
    return 0;
}
